(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-718":{scenario:{company:"Hai Van Xanh General Hospital",supervisor:{name:"Mai Thanh Tùng",role:{vi:"Trưởng phòng Quản lý Chất lượng",en:"Head of Quality Management"}},ref_code:"QI-1124",title:{vi:"Phân loại trung thực. Chỉ số đúng mẫu số. Học từ sự cố.",en:"Honest grading. Right denominator. Learn from incidents."},brief:{vi:"Đây là tình huống đào tạo. Bạn hoàn thiện báo cáo chất lượng tháng QI-1124 trình Hội đồng Quản lý chất lượng. Sự cố nổi bật: một người bệnh bị tiêm insulin gấp đôi liều, hạ đường huyết phải truyền glucose, hồi phục trong ngày và không phải kéo dài thời gian nằm viện. Tháng này có 21 ca té ngã, 840 lượt vào viện và 6000 ngày điều trị nội trú. Đối chiếu báo cáo nháp với tài liệu gốc, sửa phân loại sai sót thuốc và tỷ lệ té ngã trên 1000 ngày nằm viện, rồi lập báo cáo.",en:"This is a training scenario. You are finalizing monthly quality report QI-1124 for the Quality Management Council. Key incident: a patient received a double dose of insulin, became hypoglycaemic and needed IV glucose, recovered the same day and did not need a longer stay. This month had 21 falls, 840 admissions and 6000 inpatient days. Compare the draft with the source documents, correct the medication error category and the fall rate per 1000 patient-days, then write the report."},reference_title:{vi:"Hồ sơ sự cố & dữ liệu thống kê nội trú",en:"Incident file & inpatient statistics"},fields:[{id:"MERP_CAT",label:{vi:"Phân loại sai sót thuốc (NCC MERP)",en:"Medication error category (NCC MERP)"},initial:"NCC MERP C",expected:"NCC MERP E",choices:["NCC MERP C","NCC MERP E","NCC MERP F"],reference:"Thang phân loại NCC MERP",ref_value:{vi:"C: đến người bệnh, không gây hại; E: tổn hại tạm thời cần can thiệp; F: tổn hại tạm thời phải nhập hoặc kéo dài nằm viện",en:"C: reached patient, no harm; E: temporary harm needing intervention; F: temporary harm needing admission or longer stay"},hint:{vi:"Hạ đường huyết phải truyền glucose là tổn hại cần can thiệp; xem có kéo dài nằm viện hay không.",en:"Hypoglycaemia treated with IV glucose is harm needing intervention; check whether the stay was prolonged."}},{id:"FALL_RATE",label:{vi:"Tỷ lệ té ngã / 1000 ngày nằm viện",en:"Falls per 1000 patient-days"},initial:"2.5",expected:"3.5",reference:"Thống kê nội trú tháng 11",ref_value:{vi:"21 ca té ngã; 840 lượt vào viện; 6000 ngày điều trị nội trú",en:"21 falls; 840 admissions; 6000 inpatient days"},hint:{vi:"Bản nháp đang dùng sai mẫu số; chỉ số té ngã chuẩn tính theo ngày nằm viện.",en:"The draft uses the wrong denominator; the standard fall indicator uses patient-days."}}],sop32:{vi:"Tỷ lệ té ngã = số ca té ngã / tổng số ngày điều trị nội trú x 1000. Không dùng số lượt vào viện làm mẫu số; ghi rõ tử số, mẫu số và kỳ báo cáo.",en:"Fall rate = number of falls / total inpatient days x 1000. Never use admissions as the denominator; state numerator, denominator and reporting period."},context:{label:"IR SYSTEM / QI-1124",metrics:[{label:{vi:"Số ca té ngã",en:"Falls"},value:"21"},{label:{vi:"Lượt vào viện",en:"Admissions"},value:"840"},{label:{vi:"Ngày điều trị nội trú",en:"Inpatient days"},value:"6000"},{label:{vi:"Số ngày đến đợt đánh giá",en:"Days to quality assessment"},value:"21"}]},crisis:{vi:"Phó Giám đốc chuyên môn đề nghị: “Hạ sự cố insulin xuống mức C và bỏ khỏi báo cáo tháng, sắp có đoàn đánh giá chất lượng. Còn điều dưỡng gây lỗi thì lập biên bản kỷ luật ngay để răn đe.”",en:"The Deputy Medical Director says: “Downgrade the insulin incident to C and leave it out of the monthly report, the quality assessors are coming. And write up the nurse involved for discipline right away as a warning.”"},options:{safe:{vi:"Giữ phân loại E theo bằng chứng, báo cáo đầy đủ lên Hội đồng, tiến hành phân tích nguyên nhân gốc theo hướng hệ thống, bảo mật người báo cáo và báo Giám đốc bệnh viện về đề nghị che giấu.",en:"Keep category E as the evidence shows, report it fully to the Council, run a systems-focused root cause analysis, protect the reporter's confidentiality and inform the Hospital Director of the request to conceal."},shortcut:{vi:"Hạ xuống mức C, bỏ khỏi báo cáo tháng và lập biên bản kỷ luật điều dưỡng.",en:"Downgrade to C, drop it from the report and discipline the nurse."},wait:{vi:"Treo báo cáo tháng lại đến sau đợt đánh giá chất lượng.",en:"Hold the monthly report until after the quality assessment."}},questions:{vi:["Vì sao sự cố insulin là NCC MERP E và tỷ lệ té ngã đúng là 3,5 trên 1000 ngày nằm viện? Dẫn chứng từ hồ sơ.","Bạn thiết kế phân tích nguyên nhân gốc và giải pháp hệ thống thế nào thay vì kỷ luật cá nhân?"],en:["Why is the insulin event NCC MERP E and why is the fall rate 3.5 per 1000 patient-days? Cite the records.","How would you design the root cause analysis and system fixes instead of individual blame?"]},hints:{vi:["Đối chiếu diễn biến người bệnh với định nghĩa từng mức C, E, F trong thang NCC MERP.","Chọn đúng mẫu số ngày điều trị nội trú trước khi nhân 1000 ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không hạ mức, không che giấu sự cố; văn hóa an toàn không đổ lỗi cá nhân."],en:["Match the patient's course with the definitions of C, E and F on the NCC MERP index.","Pick inpatient days as the denominator before multiplying by 1000 in SOP 3.2.","Re-read SOP 4.2: never downgrade or hide incidents; a safety culture does not blame individuals."]}},learning:{summary:{vi:"Chuyên viên quản lý chất lượng và an toàn người bệnh xây dựng, đo lường và cải tiến chất lượng dịch vụ của bệnh viện. Người làm nghề quản lý hệ thống báo cáo sự cố, phân loại và phân tích nguyên nhân gốc, theo dõi chỉ số chất lượng, triển khai các mục tiêu an toàn người bệnh và chuẩn bị đánh giá theo bộ tiêu chí. Giá trị cốt lõi là minh bạch, học hỏi từ sai sót và văn hóa an toàn không đổ lỗi.",en:"A healthcare quality and patient safety officer builds, measures and improves the quality of hospital services. The role runs the incident reporting system, grades and analyses root causes, tracks quality indicators, rolls out patient safety goals and prepares for assessments against hospital standards. Its core values are transparency, learning from errors and a just, blame-free safety culture."},responsibilities:{vi:["Quản lý hệ thống báo cáo sự cố y khoa tự nguyện và bắt buộc, bảo mật người báo cáo.","Phân loại mức độ tổn hại, phân tích nguyên nhân gốc và theo dõi hành động khắc phục.","Xây dựng, thu thập và phân tích bộ chỉ số chất lượng với tử số, mẫu số chuẩn.","Triển khai các mục tiêu an toàn người bệnh: nhận diện, dùng thuốc, phẫu thuật, phòng té ngã.","Tổ chức tự đánh giá, chuẩn bị đánh giá chất lượng bệnh viện và báo cáo Hội đồng."],en:["Run voluntary and mandatory incident reporting and protect reporters' confidentiality.","Grade harm, analyse root causes and track corrective actions.","Define, collect and analyse quality indicators with standard numerators and denominators.","Roll out patient safety goals: identification, medication, surgery and fall prevention.","Organize self-assessments, prepare hospital quality assessments and report to the Council."]},competencies:[{name:{vi:"Khoa học an toàn người bệnh",en:"Patient safety science"},desc:{vi:"Hiểu mô hình sai sót hệ thống, yếu tố con người và nguyên tắc văn hóa công bằng.",en:"Understand system error models, human factors and just culture principles."}},{name:{vi:"Đo lường chất lượng",en:"Quality measurement"},desc:{vi:"Định nghĩa chỉ số, chọn đúng mẫu số, phân tích xu hướng bằng biểu đồ kiểm soát.",en:"Define indicators, choose correct denominators and analyse trends with control charts."}},{name:{vi:"Phân tích nguyên nhân gốc",en:"Root cause analysis"},desc:{vi:"Dẫn dắt RCA, FMEA, biểu đồ xương cá để tìm lỗ hổng hệ thống và giải pháp bền vững.",en:"Lead RCA, FMEA and fishbone sessions to find system gaps and durable fixes."}},{name:{vi:"Cải tiến liên tục",en:"Continuous improvement"},desc:{vi:"Triển khai chu trình PDCA, đo lường trước, sau và chuẩn hóa thực hành tốt.",en:"Run PDCA cycles, measure before and after and standardize good practice."}},{name:{vi:"Minh bạch & độc lập",en:"Transparency & independence"},desc:{vi:"Báo cáo trung thực dù áp lực thành tích, bảo vệ người báo cáo và người bệnh.",en:"Report honestly despite performance pressure and protect reporters and patients."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15 và quy định về quản lý chất lượng khám chữa bệnh.","Thông tư 19/2013/TT-BYT hướng dẫn quản lý chất lượng dịch vụ khám bệnh, chữa bệnh tại bệnh viện.","Thông tư 43/2018/TT-BYT hướng dẫn phòng ngừa sự cố y khoa trong cơ sở khám bệnh, chữa bệnh.","Bộ tiêu chí chất lượng bệnh viện Việt Nam ban hành theo Quyết định 6858/QĐ-BYT năm 2016.","Thang phân loại sai sót thuốc NCC MERP (A đến I) và mô hình pho mát Thụy Sĩ của James Reason.","Công cụ RCA, FMEA, PDCA, Pareto và các mục tiêu an toàn người bệnh quốc tế."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15 and rules on care quality management.","Circular 19/2013/TT-BYT on quality management of hospital services.","Circular 43/2018/TT-BYT on preventing patient safety incidents in healthcare facilities.","The Vietnam hospital quality criteria issued by Decision 6858/QD-BYT (2016).","The NCC MERP medication error index (A to I) and James Reason's Swiss cheese model.","RCA, FMEA, PDCA and Pareto tools and the international patient safety goals."]},tools:["Phần mềm báo cáo sự cố y khoa","Bảng điều khiển chỉ số chất lượng","Biểu đồ xương cá và Pareto","Biểu mẫu FMEA","Microsoft Excel / Power BI"],kpis:{vi:["Số báo cáo sự cố tự nguyện trên 1000 ngày nằm viện (tăng thể hiện văn hóa báo cáo tốt).","Tỷ lệ sự cố nghiêm trọng được hoàn thành RCA đúng hạn.","Tỷ lệ hành động khắc phục được thực hiện và kiểm chứng hiệu quả.","Xu hướng tỷ lệ té ngã, sai sót thuốc và nhiễm khuẩn bệnh viện."],en:["Voluntary incident reports per 1000 patient-days (a rise signals a healthy reporting culture).","Share of serious incidents with RCA completed on time.","Share of corrective actions implemented and verified effective.","Trends in falls, medication errors and healthcare-associated infections."]},day:[{time:"08:00",vi:"Rà soát báo cáo sự cố mới trong 24 giờ, phân loại mức tổn hại.",en:"Review incident reports from the last 24 hours and grade harm."},{time:"09:30",vi:"Đi khảo sát khoa lâm sàng, quan sát tuân thủ nhận diện người bệnh và vệ sinh tay.",en:"Walk the wards and observe patient identification and hand hygiene."},{time:"11:00",vi:"Dẫn dắt buổi phân tích nguyên nhân gốc cho sự cố nghiêm trọng.",en:"Facilitate a root cause analysis for a serious incident."},{time:"14:00",vi:"Tính chỉ số chất lượng tháng, kiểm tra tử số, mẫu số với phòng kế hoạch.",en:"Calculate monthly indicators and check numerators and denominators with planning."},{time:"16:00",vi:"Soạn báo cáo cho Hội đồng Quản lý chất lượng và theo dõi kế hoạch cải tiến.",en:"Draft the Quality Council report and follow up improvement plans."}],mistakes:{vi:["Hạ mức độ sự cố hoặc bỏ sự cố khỏi báo cáo vì sợ ảnh hưởng đánh giá.","Tính tỷ lệ té ngã theo lượt vào viện thay vì ngày nằm viện.","Kết luận lỗi cá nhân và kỷ luật thay vì tìm nguyên nhân hệ thống."],en:["Downgrading or omitting incidents for fear of a poor assessment.","Calculating falls per admission instead of per patient-day.","Blaming and disciplining individuals instead of finding system causes."]},career:[{vi:"Nhân viên mạng lưới quản lý chất lượng khoa",en:"Ward quality network member"},{vi:"Chuyên viên quản lý chất lượng & an toàn người bệnh",en:"Quality & patient safety officer"},{vi:"Phó phòng / Trưởng nhóm an toàn người bệnh",en:"Deputy head / Patient safety lead"},{vi:"Trưởng phòng Quản lý chất lượng bệnh viện",en:"Hospital Head of Quality Management"}],glossary:[{term:"Sự cố y khoa",vi:"Tình huống không mong muốn xảy ra trong quá trình chăm sóc, điều trị có thể hoặc đã gây hại cho người bệnh.",en:"An unintended event during care or treatment that could or did harm a patient."},{term:"NCC MERP",vi:"Thang phân loại sai sót thuốc từ A (có nguy cơ sai sót) đến I (sai sót góp phần gây tử vong).",en:"Medication error index from A (capacity to cause error) to I (error contributing to death)."},{term:"RCA",vi:"Phân tích nguyên nhân gốc: phương pháp có cấu trúc tìm lỗ hổng hệ thống dẫn đến sự cố.",en:"Root cause analysis: a structured method to find system gaps that led to an incident."},{term:"Just culture",vi:"Văn hóa công bằng: khuyến khích báo cáo, phân biệt lỗi hệ thống với hành vi cố ý vi phạm.",en:"A culture that encourages reporting and separates system errors from reckless conduct."},{term:"Patient-days",vi:"Ngày nằm viện: tổng số ngày điều trị nội trú của mọi người bệnh trong kỳ, mẫu số chuẩn của nhiều chỉ số.",en:"Total inpatient days of all patients in a period, the standard denominator for many indicators."}],quiz:[{q:{vi:"Tháng có 12 ca té ngã và 4800 ngày điều trị nội trú. Tỷ lệ té ngã trên 1000 ngày nằm viện là bao nhiêu?",en:"A month has 12 falls and 4800 inpatient days. What is the fall rate per 1000 patient-days?"},options:{vi:["0,25","2,5","25","4,0"],en:["0.25","2.5","25","4.0"]},answer:1,explain:{vi:"12 / 4800 x 1000 = 2,5 ca té ngã trên 1000 ngày nằm viện.",en:"12 / 4800 x 1000 = 2.5 falls per 1000 patient-days."}},{q:{vi:"Sai sót thuốc đến người bệnh nhưng không gây hại thuộc mức nào của NCC MERP?",en:"A medication error that reached the patient without harm is which NCC MERP category?"},options:{vi:["Mức A","Mức B","Mức C","Mức E"],en:["Category A","Category B","Category C","Category E"]},answer:2,explain:{vi:"Mức C: sai sót đến người bệnh, không gây hại; mức B là sai sót chưa đến người bệnh.",en:"Category C: reached the patient without harm; B means it did not reach the patient."}},{q:{vi:"Lãnh đạo đề nghị hạ mức và bỏ một sự cố khỏi báo cáo trước đợt đánh giá. Bạn làm gì?",en:"A leader asks you to downgrade and omit an incident before an assessment. What do you do?"},options:{vi:["Giữ phân loại theo bằng chứng, báo cáo đầy đủ và báo Giám đốc","Hạ mức nhưng ghi chú riêng","Bỏ khỏi báo cáo tháng này, đưa vào tháng sau","Xóa hồ sơ sự cố"],en:["Keep the evidence-based grade, report fully and inform the Director","Downgrade it with a private note","Leave it out this month and add it next month","Delete the incident file"]},answer:0,explain:{vi:"Che giấu sự cố làm mất cơ hội học hỏi và vi phạm quy định; phải minh bạch và báo cấp có thẩm quyền.",en:"Concealing incidents loses learning and breaks the rules; be transparent and escalate."}},{q:{vi:"Mục đích chính của phân tích nguyên nhân gốc (RCA) là gì?",en:"What is the main purpose of a root cause analysis (RCA)?"},options:{vi:["Xác định người phải chịu kỷ luật","Hoàn thiện hồ sơ cho đoàn đánh giá","Ước tính chi phí bồi thường","Tìm lỗ hổng hệ thống để ngăn sự cố tái diễn"],en:["Identify who to discipline","Complete paperwork for assessors","Estimate compensation costs","Find system gaps to prevent recurrence"]},answer:3,explain:{vi:"RCA tập trung vào quy trình, hệ thống, không nhằm đổ lỗi cá nhân.",en:"RCA focuses on processes and systems, not on blaming individuals."}}],tools_en:["Medical incident reporting software","Quality indicator dashboard","Fishbone and Pareto charts","FMEA templates","Microsoft Excel / Power BI"]}}})})(window.KKR);
